```bash
cat <<'EOF' > reproduce_issue.go
package main

import (
    "fmt"
    "log"
    "time"
    "github.com/allegro/bigcache/v3"
)

func main() {
    cache, err := bigcache.NewBigCache(bigcache.DefaultConfig(10 * time.Minute))
    if err != nil {
        log.Fatal(err)
    }

    // This should panic according to the issue
    err = cache.Delete("")
    fmt.Println("Error:", err)
}
EOF
```

